"""Spence structures over G = Z_2^3 x Z_m (n - 1 = 8m) with symmetry generated by (tau, u):
tau a Singer cycle (order 7) or other element of GL(3,2) acting on Z_2^3, u a multiplier on Z_m.
Prints orbit/class counts, pools for row sums 2 and 0, and the Gaussian estimate."""
import os
import sys, math
import numpy as np
from math import gcd
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import spence_lib as L
# Singer cycle on GF(8) = F2[x]/(x^3 + x + 1): multiplication by x, as a matrix on basis 1, x, x^2
TAU = np.array([[0, 0, 1], [1, 0, 1], [0, 1, 0]])
def mat_order(M, mod=2):
    I = np.eye(3, dtype=int); P = M.copy() % mod; k = 1
    while not np.array_equal(P, I): P = (P @ M) % mod; k += 1
    return k
def run(n, maxo=200):
    m = (n - 1) // 8
    assert 8 * m == n - 1
    G = L.AbGroup([2, 2, 2, m])
    units = [u for u in range(1, m) if gcd(u, m) == 1]
    seen = set(); rows = []
    for u in units:
        for tpow in (1, 0):
            T = np.linalg.matrix_power(TAU, tpow) % 2
            A = np.zeros((4, 4), dtype=int); A[:3, :3] = T; A[3, 3] = u
            key = (tpow, u)
            st = L.Structure(G, [G.perm_from_matrix(A)])
            sig = (st.O, tuple(sorted(st.sizes.tolist()))[:6], tpow)
            if st.O > maxo or (tpow, frozenset(np.unique(st.orb[:50]).tolist()), st.O) in seen: continue
            seen.add((tpow, frozenset(np.unique(st.orb[:50]).tolist()), st.O))
            est = st.estimate(samples=1500)
            if est is None: continue
            rows.append((est['lE'], u, tpow, st.O, st.C, st.pool(2), st.pool(0), est.get('lW')))
    rows.sort(key=lambda r: -r[0] if math.isfinite(r[0]) else 1e9)
    for r in rows[:12]:
        print(f"n={n} u={r[1]} tau^{r[2]} orbits={r[3]} classes={r[4]} pools=({r[5]:.3g},{r[6]:.3g}) lE={r[0]:.2f} lW={r[7]}", flush=True)
if __name__ == '__main__':
    for n in map(int, sys.argv[1:]): run(n)
